//! Generates the Thunderstore game definitions in `registry/` from its
//! ecosystem schema, the same data r2modman uses for its game list, so
//! supporting a new game there is a matter of running this again.
//!
//! ```text
//! cargo run -p registry-gen
//! ```
//!
//! Writes `games/<id>.toml` for every game r2modman installs with one of
//! [`LOADERS`], and a `rulesets/<loader>-loader.toml` for each of them from
//! the list of loader packages.
//! Generated files start with [`HEADER`]; ones whose game has left the schema
//! are deleted, and anything without the header is left alone.

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result, bail};
use clap::Parser;
use patchwork_core::game::{Detect, GAME_SCHEMA, GameDef, validate_game_id};
use serde::{Deserialize, Serialize};

const SCHEMA_URL: &str = "https://thunderstore.io/api/experimental/schema/dev/latest/";
/// Has each community's description and cover image, which the schema
/// doesn't. Undocumented, like the search API the thunderstore source uses.
const COMMUNITIES_URL: &str = "https://thunderstore.io/api/cyberstorm/community/";

const HEADER: &str = "# Generated by registry-gen from Thunderstore's ecosystem schema; changes\n\
# here are overwritten. To customize a game, put an overlay in your config\n\
# directory instead (see registry/README.md).\n";

/// The package loaders whose games are generated, as the schema names them.
/// `recursive-melonloader` is MelonLoader 0.7 and later.
const LOADERS: &[&str] = &["bepinex", "melonloader", "recursive-melonloader"];

/// Ids that predate the generator, kept so existing profiles still work.
const ID_OVERRIDES: &[(&str, &str)] = &[("riskofrain2", "risk-of-rain-2")];

#[derive(Parser)]
struct Args {
    /// The registry directory to write to.
    #[arg(long, default_value = concat!(env!("CARGO_MANIFEST_DIR"), "/../../registry"))]
    registry: PathBuf,
    /// Read the ecosystem schema from a file instead of downloading it.
    #[arg(long)]
    schema: Option<PathBuf>,
    /// Read the community listing from a file instead of downloading it.
    #[arg(long)]
    communities: Option<PathBuf>,
}

// --- Thunderstore's ecosystem schema (only the parts used here) ---

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Schema {
    games: BTreeMap<String, SchemaGame>,
    modloader_packages: Vec<LoaderPackage>,
}

#[derive(Deserialize)]
struct SchemaGame {
    #[serde(default)]
    r2modman: Option<Vec<R2Game>>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct R2Game {
    meta: Meta,
    distributions: Vec<Distribution>,
    steam_folder_name: Option<String>,
    #[serde(default)]
    exe_names: Vec<String>,
    game_instance_type: String,
    package_loader: Option<String>,
    install_rules: Vec<InstallRule>,
    relative_file_exclusions: Option<Vec<String>>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Meta {
    display_name: String,
}

#[derive(Deserialize)]
struct Distribution {
    platform: String,
    identifier: Option<String>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct InstallRule {
    route: String,
    default_file_extensions: Vec<String>,
    tracking_method: String,
    sub_routes: Vec<InstallRule>,
    is_default_location: bool,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct LoaderPackage {
    package_id: String,
    root_folder: String,
    loader: String,
}

#[derive(Deserialize)]
struct Communities {
    next: Option<String>,
    results: Vec<Community>,
}

#[derive(Deserialize)]
struct Community {
    identifier: String,
    short_description: Option<String>,
    cover_image_url: Option<String>,
}

// --- What gets written ---

/// A game definition as written out. Its own type rather than [`GameDef`]
/// so the fields come out in a readable order.
#[derive(Serialize)]
struct GameFile {
    schema: u32,
    id: String,
    name: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    description: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    image: Option<String>,
    sources: Sources,
    deployer: Deployer,
    #[serde(skip_serializing_if = "Detect::is_empty")]
    detect: Detect,
}

#[derive(Serialize)]
struct Sources {
    thunderstore: Thunderstore,
}

#[derive(Serialize)]
struct Thunderstore {
    community: String,
}

#[derive(Serialize)]
struct Deployer {
    kind: &'static str,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    rulesets: Vec<String>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    rules: Vec<Rule>,
}

/// A rule for the `rules` deployer.
#[derive(Serialize, Deserialize, Default, Debug, PartialEq)]
#[serde(deny_unknown_fields)]
struct Rule {
    #[serde(skip_serializing_if = "Option::is_none")]
    ruleset: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    files: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    folder: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    to: Option<String>,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    skip: bool,
}

#[tokio::main]
async fn main() -> Result<()> {
    let args = Args::parse();
    let client = reqwest::Client::builder()
        .user_agent(concat!(
            "patchwork-registry-gen/",
            env!("CARGO_PKG_VERSION")
        ))
        .build()?;

    let schema: Schema = match &args.schema {
        Some(path) => serde_json_file(path)?,
        None => fetch(&client, SCHEMA_URL).await?,
    };
    let communities = match &args.communities {
        Some(path) => serde_json_file::<Communities>(path)?.results,
        None => {
            let mut all = Vec::new();
            let mut url = Some(COMMUNITIES_URL.to_owned());
            while let Some(next) = url {
                let page: Communities = fetch(&client, &next).await?;
                all.extend(page.results);
                url = page.next;
            }
            all
        }
    };
    let communities: BTreeMap<_, _> = communities
        .into_iter()
        .map(|c| (c.identifier.clone(), c))
        .collect();

    let games = generate_games(&schema, &communities)?;
    let rulesets = generate_loader_rulesets(&schema)?;

    let games_dir = args.registry.join("games");
    fs::create_dir_all(&games_dir)?;
    let mut written = BTreeSet::new();
    for (id, text) in &games {
        fs::write(games_dir.join(format!("{id}.toml")), text)?;
        written.insert(format!("{id}.toml"));
    }
    let mut removed = 0;
    for entry in fs::read_dir(&games_dir)? {
        let path = entry?.path();
        let name = path.file_name().unwrap_or_default().to_string_lossy();
        if !written.contains(name.as_ref())
            && fs::read_to_string(&path).is_ok_and(|text| text.starts_with(HEADER))
        {
            fs::remove_file(&path)?;
            removed += 1;
        }
    }
    for (id, text) in &rulesets {
        fs::write(args.registry.join(format!("rulesets/{id}.toml")), text)?;
    }
    println!(
        "wrote {} games and {} loader rulesets to {}; removed {removed} stale games",
        games.len(),
        rulesets.len(),
        args.registry.display()
    );
    Ok(())
}

async fn fetch<T: serde::de::DeserializeOwned>(client: &reqwest::Client, url: &str) -> Result<T> {
    client
        .get(url)
        .send()
        .await
        .and_then(|r| r.error_for_status())
        .with_context(|| format!("downloading {url}"))?
        .json()
        .await
        .with_context(|| format!("reading {url}"))
}

fn serde_json_file<T: serde::de::DeserializeOwned>(path: &Path) -> Result<T> {
    let text = fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;
    serde_json::from_str(&text).with_context(|| format!("parsing {}", path.display()))
}

/// Every game in the schema that uses one of [`LOADERS`], as
/// `(id, file contents)`.
fn generate_games(
    schema: &Schema,
    communities: &BTreeMap<String, Community>,
) -> Result<Vec<(String, String)>> {
    let mut out = Vec::new();
    let mut ids = BTreeSet::new();
    for (key, game) in &schema.games {
        let variants = game.r2modman.as_deref().unwrap_or_default();
        let base = ID_OVERRIDES
            .iter()
            .find(|(k, _)| k == key)
            .map_or(key.as_str(), |(_, id)| id);
        let community = communities.get(key);
        for (i, r2) in variants.iter().enumerate() {
            if !r2
                .package_loader
                .as_deref()
                .is_some_and(|l| LOADERS.contains(&l))
            {
                continue;
            }
            // The first variant is the game itself; the rest are servers or
            // other editions that share its community.
            let id = if i == 0 {
                base.to_owned()
            } else if r2.game_instance_type == "server" {
                format!("{base}-server")
            } else {
                slug(&r2.meta.display_name)
            };
            validate_game_id(&id)?;
            if !ids.insert(id.clone()) {
                bail!("two games would both be `{id}`");
            }
            let file =
                game_file(key, &id, r2, community).with_context(|| format!("generating `{id}`"))?;
            let text = format!("{HEADER}\n{}", toml::to_string(&file)?);
            // Anything written has to load.
            let def: GameDef =
                toml::from_str(&text).with_context(|| format!("`{id}` doesn't parse"))?;
            assert_eq!(def.id, id);
            out.push((id, text));
        }
    }
    Ok(out)
}

fn game_file(
    community: &str,
    id: &str,
    r2: &R2Game,
    listing: Option<&Community>,
) -> Result<GameFile> {
    let nonempty = |s: &Option<String>| s.as_ref().filter(|s| !s.trim().is_empty()).cloned();
    let loader = r2.package_loader.as_deref().unwrap_or_default();
    let (rulesets, rules) = match loader {
        // r2modman ignores the install rules for these and puts each mod in
        // a folder of its own, which the ruleset does for every game.
        "recursive-melonloader" => (vec![loader.to_owned()], Vec::new()),
        "bepinex" if is_standard(r2) => (vec![loader.to_owned()], Vec::new()),
        _ => {
            let mut rules = vec![Rule {
                ruleset: Some(format!("{loader}-loader")),
                ..Rule::default()
            }];
            rules.extend(mod_rules(r2)?);
            (Vec::new(), rules)
        }
    };
    Ok(GameFile {
        schema: GAME_SCHEMA,
        id: id.to_owned(),
        name: r2.meta.display_name.clone(),
        description: listing.and_then(|c| nonempty(&c.short_description)),
        image: listing.and_then(|c| nonempty(&c.cover_image_url)),
        sources: Sources {
            thunderstore: Thunderstore {
                community: community.to_owned(),
            },
        },
        deployer: Deployer {
            kind: "rules",
            rulesets,
            rules,
        },
        detect: Detect {
            steam: r2
                .distributions
                .iter()
                .filter(|d| d.platform == "steam")
                .filter_map(|d| d.identifier.as_deref()?.parse().ok())
                .collect(),
            gog: Vec::new(),
            // what r2modman launches it by, which is its app name
            epic: r2
                .distributions
                .iter()
                .filter(|d| d.platform == "epic-games-store")
                .filter_map(|d| d.identifier.clone())
                .filter(|id| !id.is_empty())
                .collect(),
            folder: r2.steam_folder_name.clone().filter(|f| !f.is_empty()),
            exe: r2.exe_names.clone(),
            version: Vec::new(),
        },
    })
}

/// Whether a game installs mods exactly like `rulesets/bepinex.toml`, which
/// nearly all of them do.
fn is_standard(r2: &R2Game) -> bool {
    let standard = [
        ("BepInEx/plugins", "subdir", &[".dll"][..], true),
        ("BepInEx/core", "subdir", &[], false),
        ("BepInEx/patchers", "subdir", &[], false),
        ("BepInEx/monomod", "subdir", &[".mm.dll"], false),
        ("BepInEx/config", "none", &[], false),
    ];
    r2.relative_file_exclusions
        .as_ref()
        .is_none_or(Vec::is_empty)
        && r2.install_rules.len() == standard.len()
        && r2
            .install_rules
            .iter()
            .zip(standard)
            .all(|(rule, (route, tracking, exts, default))| {
                rule.route == route
                    && rule.tracking_method == tracking
                    && rule.default_file_extensions == exts
                    && rule.is_default_location == default
                    && rule.sub_routes.is_empty()
            })
}

/// A route with its sub-routes' paths filled in, as r2modman's
/// `InstallationRules.getAllManagedPaths` lists them.
struct Route<'a> {
    rule: &'a InstallRule,
    /// Its path in the game directory.
    path: String,
}

fn flatten<'a>(rules: &'a [InstallRule], parent: Option<&str>, out: &mut Vec<Route<'a>>) {
    for rule in rules {
        let path = match parent {
            Some(parent) => format!("{parent}/{}", rule.route),
            None => rule.route.clone(),
        };
        out.push(Route {
            rule,
            path: path.clone(),
        });
        flatten(&rule.sub_routes, Some(&path), out);
    }
}

/// Where a route puts a mod's files: the folder, and what goes after it for
/// a file that isn't in a folder named after the route.
fn destination(route: &Route) -> Result<(String, &'static str)> {
    let path = &route.path;
    Ok(match route.rule.tracking_method.as_str() {
        // Flattened: the file loses the folders it was in.
        "state" | "none" => (path.clone(), "{file}"),
        "subdir" => (format!("{path}/{{mod}}"), "{file}"),
        // Kept where it was in the package.
        "subdir-no-flatten" => (format!("{path}/{{mod}}"), "{path}"),
        other => bail!("{path} uses tracking method `{other}`, which isn't supported"),
    })
}

/// Rules for a game's mods (not the loader), following r2modman's
/// InstallRulePluginInstaller: a folder named after a route goes to that
/// route; other files go by their longest matching extension, or to the
/// default route.
fn mod_rules(r2: &R2Game) -> Result<Vec<Rule>> {
    let mut routes = Vec::new();
    flatten(&r2.install_rules, None, &mut routes);
    let mut rules = Vec::new();

    // r2modman only leaves these out of routes tracked by `state`, where
    // they'd be in the way of each other.
    let excluded: Vec<_> = r2
        .relative_file_exclusions
        .iter()
        .flatten()
        .filter(|name| {
            route_for_file(&routes, name).is_some_and(|r| r.rule.tracking_method == "state")
        })
        .cloned()
        .collect();
    if !excluded.is_empty() {
        rules.push(Rule {
            files: Some(alternatives(&excluded)),
            skip: true,
            ..Rule::default()
        });
    }

    let mut folders = BTreeSet::new();
    let mut extensions = Vec::new();
    let mut default = None;
    for route in &routes {
        let (dest, file) = destination(route)?;
        let folder = route.path.rsplit('/').next().unwrap_or(&route.path);
        // r2modman picks between routes with the same folder name by how
        // much of the rest of the path matches, which rules can't do.
        if !folders.insert(folder.to_lowercase()) {
            bail!("more than one route is a folder named `{folder}`");
        }
        rules.push(Rule {
            folder: Some(folder.to_owned()),
            to: Some(format!("{dest}/{{path}}")),
            ..Rule::default()
        });
        let to = format!("{dest}/{file}");
        for ext in &route.rule.default_file_extensions {
            extensions.push((ext.clone(), to.clone()));
        }
        if route.rule.is_default_location {
            default = Some(to);
        }
    }

    // Longest first, so `.mm.dll` beats `.dll`.
    extensions.sort_by_key(|(ext, _)| std::cmp::Reverse(ext.len()));
    let default = default.context("no default route")?;
    for (ext, to) in extensions {
        // Files with the default route's extensions end up there anyway.
        if to != default {
            rules.push(Rule {
                files: Some(format!("**/*{ext}")),
                to: Some(to),
                ..Rule::default()
            });
        }
    }
    rules.push(Rule {
        files: Some("**".to_owned()),
        to: Some(default),
        ..Rule::default()
    });
    Ok(rules)
}

/// The route r2modman sends a file named `name` to when it isn't in a route's
/// folder: the one with the longest matching extension, or the default.
fn route_for_file<'a>(routes: &'a [Route<'a>], name: &str) -> Option<&'a Route<'a>> {
    let name = name.to_lowercase();
    routes
        .iter()
        .filter_map(|r| {
            let ext = r
                .rule
                .default_file_extensions
                .iter()
                .filter(|e| name.ends_with(&e.to_lowercase()))
                .map(String::len)
                .max()?;
            Some((ext, r))
        })
        .max_by_key(|(len, _)| *len)
        .map(|(_, r)| r)
        .or_else(|| routes.iter().find(|r| r.rule.is_default_location))
}

/// A `<loader>-loader` ruleset for each of [`LOADERS`], as `(id, contents)`.
fn generate_loader_rulesets(schema: &Schema) -> Result<Vec<(String, String)>> {
    Ok(vec![
        (
            "bepinex-loader".to_owned(),
            generate_loader_ruleset(schema)?,
        ),
        (
            "melonloader-loader".to_owned(),
            melonloader_ruleset(
                schema,
                "melonloader",
                "# MelonLoader before 0.7, installed like r2modman's MelonLoaderInstaller\n\
                 # does: everything in the pack but its metadata goes in the game directory.\n\n",
                &[("{manifest.json,icon.png,README.md}", true), ("**", false)],
            )?,
        ),
        (
            "recursive-melonloader-loader".to_owned(),
            melonloader_ruleset(
                schema,
                "recursive-melonloader",
                "# MelonLoader 0.7 and later, installed like r2modman's\n\
                 # RecursiveMelonLoaderInstaller does: only the loader's own files go in the\n\
                 # game directory. Its proxy DLL is version.dll or winhttp.dll.\n\n",
                &[
                    ("{MelonLoader/**,version.dll,winhttp.dll}", false),
                    ("**", true),
                ],
            )?,
        ),
    ])
}

/// A ruleset for a loader whose packs are recognized by name: each of
/// `rules`, as `(files, skip)`, for every pack the schema lists for `loader`.
fn melonloader_ruleset(
    schema: &Schema,
    loader: &str,
    comment: &str,
    rules: &[(&str, bool)],
) -> Result<String> {
    let mut ids: Vec<_> = schema
        .modloader_packages
        .iter()
        .filter(|p| p.loader == loader)
        .map(|p| p.package_id.clone())
        .collect();
    if ids.is_empty() {
        bail!("the schema lists no {loader} loader packages");
    }
    ids.sort_by_key(|id| id.to_lowercase());
    ids.dedup();
    let mods = toml_list(&ids);
    let mut out = format!("{HEADER}\n{comment}");
    for (files, skip) in rules {
        out += &format!("[[rules]]\nmods = {mods}\nfiles = {}\n", toml_str(files));
        if *skip {
            out += "skip = true\n";
        }
        out += "\n";
    }
    out += MELONLOADER_CONFIG;
    Ok(out.trim_end().to_owned() + "\n")
}

/// Every version of MelonLoader keeps all of its mods' settings in one
/// TOML file, which patchwork shows on the Config tab.
const MELONLOADER_CONFIG: &str = "# Every mod's settings, which MelonLoader keeps in one TOML file.\n\
[[config]]\n\
files = \"UserData/MelonPreferences.cfg\"\n\
format = \"generic.toml\"\n";

/// `rulesets/bepinex-loader.toml`, from the schema's list of loader packages.
/// r2modman's BepInExInstaller copies the contents of a pack's root folder
/// into the game directory and ignores the rest of it.
fn generate_loader_ruleset(schema: &Schema) -> Result<String> {
    let packages: Vec<_> = schema
        .modloader_packages
        .iter()
        .filter(|p| p.loader == "bepinex")
        .collect();
    if packages.is_empty() {
        bail!("the schema lists no BepInEx loader packages");
    }
    let mut ids: Vec<_> = packages.iter().map(|p| p.package_id.clone()).collect();
    ids.sort_by_key(|id| id.to_lowercase());
    ids.dedup();
    // `BepInExPack*` also catches packs added from a local zip, whatever
    // they're called. Roots it doesn't cover are listed as well.
    let mut roots = vec!["BepInExPack*".to_owned()];
    let mut rootless = Vec::new();
    for p in &packages {
        if p.root_folder.is_empty() {
            rootless.push(p.package_id.clone());
        } else if !p.root_folder.starts_with("BepInExPack") && !roots.contains(&p.root_folder) {
            roots.push(p.root_folder.clone());
        }
    }
    roots[1..].sort();
    rootless.sort();
    rootless.dedup();

    let mut out = format!(
        "{HEADER}\n\
         # BepInEx itself, installed like r2modman's BepInExInstaller does: the\n\
         # contents of a loader pack's root folder go in the game directory, and\n\
         # the rest of the pack is left out.\n\n"
    );
    out += "# Matched by folder rather than by name, so a pack from a local zip works too.\n";
    out += &format!(
        "[[rules]]\nfiles = {}\nstrip = 1\n\n",
        toml_str(&format!("{}/**", alternatives(&roots)))
    );
    if !rootless.is_empty() {
        let mods = toml_list(&rootless);
        out += "# Packs without a root folder. Their metadata isn't part of the loader.\n";
        out += &format!(
            "[[rules]]\nmods = {mods}\nfiles = \"{{manifest.json,icon.png,README.md}}\"\nskip = true\n\n"
        );
        out += &format!("[[rules]]\nmods = {mods}\nfiles = \"**\"\n\n");
    }
    out += "[[rules]]\nfiles = \"**\"\nskip = true\nmods = ";
    out += &toml_list(&ids);
    out += "\n";
    Ok(out)
}

/// A glob matching any of `names`.
fn alternatives(names: &[String]) -> String {
    match names {
        [one] => one.clone(),
        _ => format!("{{{}}}", names.join(",")),
    }
}

fn toml_str(s: &str) -> String {
    toml::Value::String(s.to_owned()).to_string()
}

/// One item per line, which reads better and diffs better for long lists.
fn toml_list(items: &[String]) -> String {
    match items {
        [one] => toml_str(one),
        _ => {
            let mut out = String::from("[\n");
            for item in items {
                out += &format!("    {},\n", toml_str(item));
            }
            out + "]"
        }
    }
}

/// `"Outward Definitive"` → `outward-definitive`.
fn slug(name: &str) -> String {
    let mut out = String::new();
    for c in name.chars() {
        if c.is_ascii_alphanumeric() {
            out.push(c.to_ascii_lowercase());
        } else if !out.is_empty() && !out.ends_with('-') {
            out.push('-');
        }
    }
    out.trim_end_matches('-').to_owned()
}

#[cfg(test)]
mod tests;
